 isolation_cell_enable_pin : true;
 direction : input;
 related_ground_pin : VSS;
 related_power_pin : VDD;
 }
 pin(CK_OUT) {
 direction : output;
 power_down_function : "!VDD + VSS";
 related_ground_pin : VSS;
 related_power_pin : VDD;
 state_function : "CK * Q";
 timing() {
 related_pin : "CK";
 timing_sense : "positive_unate";
 }
 }
